import java.util.*;

class Solution {
    public int pathSum(TreeNode root, int targetSum) {
        Map<Long, Integer> prefixMap = new HashMap<>();
        prefixMap.put(0L, 1);
        return dfs(root, 0L, targetSum, prefixMap);
    }

    private int dfs(TreeNode node, long currentSum, int target, Map<Long, Integer> prefixMap) {
        if (node == null) return 0;

        currentSum += node.val;
        int count = prefixMap.getOrDefault(currentSum - target, 0);

        prefixMap.merge(currentSum, 1, Integer::sum);

        count += dfs(node.left, currentSum, target, prefixMap);
        count += dfs(node.right, currentSum, target, prefixMap);

        prefixMap.merge(currentSum, -1, Integer::sum);

        return count;
    }
}

class Solution {
    public int pathSum(TreeNode root, int targetSum) {
        if (root == null) return 0;

        return countFrom(root, targetSum)
            + pathSum(root.left, targetSum)
            + pathSum(root.right, targetSum);
    }

    private int countFrom(TreeNode node, long remain) {
        if (node == null) return 0;

        int count = (node.val == remain) ? 1 : 0;
        count += countFrom(node.left, remain - node.val);
        count += countFrom(node.right, remain - node.val);

        return count;
    }
}
